"use client";

import React from "react";
import { cn } from "@/lib/utils";
import { springLinear } from "./motion-curves";

export interface TextAnimationProps extends React.HTMLAttributes<HTMLDivElement> {
  text: string;
  variant?:
    | "typewriter"
    | "blur-reveal"
    | "wave"
    | "pop-in"
    | "flip"
    | "spin-in"
    | "blur-in-up";
  duration?: number;
  delay?: number;
  as?: React.ElementType;
  /**
   * Swap what a word renders as, keeping its entrance. Word-level variants
   * only (`pop-in`, `flip`, `blur-in-up`): return the word itself with some
   * markup, e.g. a coloured span or a word that later changes.
   */
  renderWord?: (word: string, index: number) => React.ReactNode;
}

type Variant = NonNullable<TextAnimationProps["variant"]>;
type TokenVariant = Exclude<Variant, "blur-reveal">;

// ==========================================
// ENTRANCES
// ==========================================
// Plain CSS keyframes, no animation library. The springs are the same
// stiffness / damping curves as before, solved once into CSS `linear()`
// easings (the analytic spring, sampled at 120 points a second). A spring
// drives every value of its token — opacity included, where the overshoot
// simply clamps at 1.

interface Entrance {
  from: string;
  to: string;
  /** ms */
  duration: number;
  easing: string;
}

const spring = (stiffness: number, damping: number) =>
  springLinear({ stiffness, damping }, 120);

const TOKEN_ENTRANCES: Record<TokenVariant, Entrance> = {
  typewriter: {
    from: "opacity: 0; transform: translateY(10px);",
    to: "opacity: 1; transform: translateY(0px);",
    ...spring(100, 12),
  },
  wave: {
    from: "opacity: 0; transform: translateY(15px);",
    to: "opacity: 1; transform: translateY(0px);",
    ...spring(200, 10),
  },
  "pop-in": {
    from: "opacity: 0; transform: translateY(10px) scale(0.5);",
    to: "opacity: 1; transform: translateY(0px) scale(1);",
    ...spring(200, 12),
  },
  flip: {
    from: "opacity: 0; transform: translateY(20px) rotateX(-90deg);",
    to: "opacity: 1; transform: translateY(0px) rotateX(0deg);",
    ...spring(200, 15),
  },
  "spin-in": {
    from: "opacity: 0; transform: scale(0) rotate(-180deg);",
    to: "opacity: 1; transform: scale(1) rotate(0deg);",
    ...spring(200, 12),
  },
  "blur-in-up": {
    from: "opacity: 0; transform: translateY(20px); filter: blur(8px);",
    to: "opacity: 1; transform: translateY(0px); filter: blur(0px);",
    duration: 600,
    easing: "cubic-bezier(0, 0, 0.58, 1)",
  },
};

/** Seconds between neighbouring tokens (typewriter's depends on `duration`). */
const STAGGER: Record<Exclude<TokenVariant, "typewriter">, number> = {
  wave: 0.05,
  "pop-in": 0.1,
  flip: 0.1,
  "spin-in": 0.05,
  "blur-in-up": 0.1,
};

/**
 * Everything waits paused on its first frame until the text scrolls into
 * view, then plays once. `backwards` fill hands over to the resting styles
 * when an entrance ends. Selectors are data attributes, so nothing is added
 * to — or merged away from — the classes you pass.
 */
const PAUSED = `
[data-text-animation-state="hidden"],
[data-text-animation-state="hidden"] [data-text-animation-token] { animation-play-state: paused; }`;

function variantCss(variant: Variant) {
  if (variant === "blur-reveal") {
    return `
@keyframes text-animation-blur-reveal {
  from { opacity: 0; filter: blur(10px); transform: scale(0.95); }
  to { opacity: 1; filter: blur(0px); transform: scale(1); }
}
[data-text-animation="blur-reveal"] { animation: text-animation-blur-reveal 0.5s cubic-bezier(0, 0, 0.58, 1) backwards; }${PAUSED}`;
  }
  const entrance = TOKEN_ENTRANCES[variant];
  if (!entrance) return "";
  const { from, to, duration, easing } = entrance;
  return `
@keyframes text-animation-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes text-animation-${variant} { from { ${from} } to { ${to} } }
[data-text-animation="${variant}"] { animation: text-animation-fade 0.3s cubic-bezier(0.25, 0.1, 0.35, 1) backwards; }
[data-text-animation="${variant}"] [data-text-animation-token] { animation: text-animation-${variant} ${duration}ms ${easing} backwards; }${PAUSED}`;
}

// Built once per variant, on first use, and shared by every instance.
const cssCache: Partial<Record<Variant, string>> = {};
const cssFor = (variant: Variant) => (cssCache[variant] ??= variantCss(variant));

/** `delay + index * stagger` seconds, as a CSS time. */
const delayAt = (delay: number, index: number, stagger: number) =>
  `${Math.round((delay + index * stagger) * 100000) / 100}ms`;

export const TextAnimation = React.forwardRef<
  HTMLDivElement,
  TextAnimationProps
>(
  (
    {
      text,
      variant = "blur-reveal",
      duration = 0.5,
      delay = 0,
      as: Component = "p",
      renderWord,
      className,
      ...props
    },
    ref
  ) => {
    const outerRef = React.useRef<HTMLDivElement | null>(null);
    const innerRef = React.useRef<HTMLElement | null>(null);
    const [inView, setInView] = React.useState(false);

    const setOuterRef = React.useCallback(
      (node: HTMLDivElement | null) => {
        outerRef.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) ref.current = node;
      },
      [ref],
    );

    // Plays once, the first time any part of the text enters the viewport
    // (threshold 0). A custom `as` that doesn't forward its ref falls back
    // to observing the wrapper.
    React.useEffect(() => {
      if (inView) return;
      const el = innerRef.current ?? outerRef.current;
      if (!el || typeof IntersectionObserver === "undefined") {
        setInView(true);
        return;
      }
      const io = new IntersectionObserver((entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          setInView(true);
          io.disconnect();
        }
      });
      io.observe(el);
      return () => io.disconnect();
    }, [inView]);

    const state = inView ? "visible" : "hidden";

    const renderAnimation = () => {
      switch (variant) {
        case "typewriter": {
          const stagger = duration / text.length;
          let charIndex = 0;

          return (
            <Component
              ref={innerRef}
              data-text-animation={variant}
              data-text-animation-state={state}
              className={cn("flex flex-wrap gap-[0.25em]", className)}
            >
              {text.split(" ").map((word, index) => (
                <span key={index} className="inline-flex">
                  {word.split("").map((char, i) => (
                    <span
                      key={i}
                      data-text-animation-token=""
                      className="inline-block"
                      style={{ animationDelay: delayAt(delay, charIndex++, stagger) }}
                    >
                      {char === " " ? "\u00A0" : char}
                    </span>
                  ))}
                </span>
              ))}
            </Component>
          );
        }



        case "blur-reveal": {
          return (
            <Component
              ref={innerRef}
              data-text-animation={variant}
              data-text-animation-state={state}
              className={className}
              style={{ animationDuration: `${duration}s`, animationDelay: `${delay}s` }}
            >
              {text}
            </Component>
          );
        }



        case "wave":
        case "spin-in": {
          const stagger = STAGGER[variant];
          let charIndex = 0;

          return (
            <Component
              ref={innerRef}
              data-text-animation={variant}
              data-text-animation-state={state}
              className={cn("flex flex-wrap gap-[0.25em]", className)}
            >
              {text.split(" ").map((word, index) => (
                <span key={index} className="inline-flex">
                  {word.split("").map((char, i) => (
                    <span
                      key={i}
                      data-text-animation-token=""
                      className="inline-block"
                      style={{ animationDelay: delayAt(delay, charIndex++, stagger) }}
                    >
                      {char}
                    </span>
                  ))}
                </span>
              ))}
            </Component>
          );
        }

        case "pop-in":
        case "flip":
        case "blur-in-up": {
          const stagger = STAGGER[variant];

          return (
            <Component
              ref={innerRef}
              data-text-animation={variant}
              data-text-animation-state={state}
              className={cn(
                "flex flex-wrap gap-[0.25em]",
                variant === "flip" && "perspective-[1000px]",
                className,
              )}
            >
              {text.split(" ").map((word, index) => (
                <span
                  key={index}
                  data-text-animation-token=""
                  className={cn("inline-block", variant === "flip" && "origin-bottom")}
                  style={{ animationDelay: delayAt(delay, index, stagger) }}
                >
                  {renderWord ? renderWord(word, index) : word}
                </span>
              ))}
            </Component>
          );
        }

        default:
          return <Component className={className}>{text}</Component>;
      }
    };

    return (
      <div ref={setOuterRef} {...props}>
        {renderAnimation()}
        <style>{cssFor(variant)}</style>
      </div>
    );
  }
);

TextAnimation.displayName = "TextAnimation";

/**
 * Motion curves with no animation library behind them.
 *
 * The components here ship as CSS, GSAP or Motion builds that must move
 * identically, so the curves are computed once, from the same numbers, and
 * handed to whichever engine runs them:
 *
 *   - `cubicBezier(x1, y1, x2, y2)` → an easing function (GSAP accepts any
 *     `(progress) => value` as `ease`), exact for Motion's `ease: [..]` arrays
 *     and for CSS `cubic-bezier()`.
 *   - `spring({ stiffness, damping, mass })` → the analytic solution Motion
 *     Motion uses, as an easing function plus the time it takes to settle, or
 *     as a CSS `linear()` string for a fixed start and end.
 *   - `createSpringFollower` → a value that chases a moving target through the
 *     same spring every frame, like Motion's `useSpring`, for pointer-driven
 *     motion that no fixed curve can describe.
 */

// ---------------------------------------------------------------------------
// Cubic bezier
// ---------------------------------------------------------------------------

/**
 * The CSS / Motion cubic-bezier as a function of progress. Newton-Raphson
 * with a bisection fallback, the same solver browsers use.
 */
export function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  if (x1 === y1 && x2 === y2) return (t: number) => t;

  const a = (p1: number, p2: number) => 1 - 3 * p2 + 3 * p1;
  const b = (p1: number, p2: number) => 3 * p2 - 6 * p1;
  const c = (p1: number) => 3 * p1;
  const at = (t: number, p1: number, p2: number) =>
    ((a(p1, p2) * t + b(p1, p2)) * t + c(p1)) * t;
  const slope = (t: number, p1: number, p2: number) =>
    3 * a(p1, p2) * t * t + 2 * b(p1, p2) * t + c(p1);

  const solveX = (x: number) => {
    let t = x;
    for (let i = 0; i < 8; i++) {
      const s = slope(t, x1, x2);
      if (Math.abs(s) < 1e-6) break;
      const err = at(t, x1, x2) - x;
      if (Math.abs(err) < 1e-7) return t;
      t -= err / s;
    }
    let lo = 0;
    let hi = 1;
    t = x;
    for (let i = 0; i < 30 && hi - lo > 1e-7; i++) {
      const value = at(t, x1, x2);
      if (value < x) lo = t;
      else hi = t;
      t = (lo + hi) / 2;
    }
    return t;
  };

  return (x: number) => (x <= 0 ? 0 : x >= 1 ? 1 : at(solveX(x), y1, y2));
}

/** Motion's named eases, as the cubic-beziers they are. */
export const MOTION_EASE = {
  linear: [0, 0, 1, 1],
  easeIn: [0.42, 0, 1, 1],
  easeOut: [0, 0, 0.58, 1],
  easeInOut: [0.42, 0, 0.58, 1],
  circIn: [0.55, 0, 1, 0.45],
  circOut: [0.55, 0, 0.45, 1],
  circInOut: [0.85, 0, 0.15, 1],
  backIn: [0.31, 0.01, 0.66, -0.59],
  backOut: [0.33, 1.53, 0.69, 0.99],
  anticipate: [0.66, -0.56, 0.34, 1.35],
} as const;

/**
 * Motion's default layout transition (`layout` / `layoutId`):
 * `{ duration: 0.45, ease: [0.4, 0, 0.1, 1] }`.
 */
export const LAYOUT_TRANSITION = { duration: 0.45, ease: [0.4, 0, 0.1, 1] as const };

// ---------------------------------------------------------------------------
// Spring
// ---------------------------------------------------------------------------

export interface SpringOptions {
  /** Motion default 100. */
  stiffness?: number;
  /** Motion default 10. */
  damping?: number;
  /** Motion default 1. */
  mass?: number;
  /** Starting velocity, in units of the whole distance per second. */
  velocity?: number;
  /** How close to the end counts as settled, as a fraction of the distance. */
  restDelta?: number;
}

/**
 * Normalised position (0 → 1) of a spring released from 0 towards 1, at time
 * `t` seconds. The closed-form solution Motion's `spring()` generator
 * uses for the under-, critically and over-damped cases.
 */
export function springAt(options: SpringOptions = {}) {
  const { stiffness = 100, damping = 10, mass = 1, velocity = 0 } = options;
  const zeta = damping / (2 * Math.sqrt(stiffness * mass));
  const omega0 = Math.sqrt(stiffness / mass);
  // Motion's convention: distance still to cover, velocity toward it negated.
  const delta = 1;
  const v0 = -velocity;

  if (zeta < 1) {
    const omegaD = omega0 * Math.sqrt(1 - zeta * zeta);
    return (t: number) => {
      const envelope = Math.exp(-zeta * omega0 * t);
      return (
        1 -
        envelope *
          (((v0 + zeta * omega0 * delta) / omegaD) * Math.sin(omegaD * t) +
            delta * Math.cos(omegaD * t))
      );
    };
  }
  if (zeta === 1) {
    return (t: number) => 1 - Math.exp(-omega0 * t) * (delta + (v0 + omega0 * delta) * t);
  }
  const omegaD = omega0 * Math.sqrt(zeta * zeta - 1);
  return (t: number) => {
    const envelope = Math.exp(-zeta * omega0 * t);
    const freq = Math.min(omegaD * t, 300);
    return (
      1 -
      (envelope *
        ((v0 + zeta * omega0 * delta) * Math.sinh(freq) + omegaD * delta * Math.cosh(freq))) /
        omegaD
    );
  };
}

/** Seconds until the spring stays within `restDelta` of its end. */
export function springDuration(options: SpringOptions = {}) {
  const at = springAt(options);
  const restDelta = options.restDelta ?? 0.001;
  const step = 1 / 240;
  let lastOutside = 0;
  for (let t = 0; t <= 10; t += step) {
    if (Math.abs(1 - at(t)) > restDelta) lastOutside = t;
    else if (t - lastOutside > 0.1) break;
  }
  return Math.max(lastOutside + step, step);
}

/**
 * A spring as a duration and an easing function over it — what GSAP takes:
 *
 *   const { duration, ease } = springEase({ stiffness: 300, damping: 20 });
 *   gsap.to(el, { y: 0, duration, ease });
 *
 * Exact for a fixed start and end; a spring that has to react mid-flight to a
 * new target needs `createSpringFollower` instead.
 */
export function springEase(options: SpringOptions = {}) {
  const duration = springDuration(options);
  const at = springAt(options);
  return {
    duration,
    ease: (progress: number) => (progress >= 1 ? 1 : at(progress * duration)),
  };
}

/**
 * A spring as a CSS `linear()` easing and its duration in ms, for
 * `transition` / `animation` with a fixed start and end.
 *
 *   const { easing, duration } = springLinear({ stiffness: 400, damping: 30 });
 *   el.style.transition = `transform ${duration}ms ${easing}`;
 */
export function springLinear(options: SpringOptions = {}, pointsPerSecond = 60) {
  const duration = springDuration(options);
  const at = springAt(options);
  const count = Math.max(Math.ceil(duration * pointsPerSecond), 8);
  const points: string[] = [];
  for (let i = 0; i <= count; i++) {
    const t = (i / count) * duration;
    points.push(String(Math.round((i === count ? 1 : at(t)) * 10000) / 10000));
  }
  return { easing: `linear(${points.join(", ")})`, duration: Math.round(duration * 1000) };
}

// ---------------------------------------------------------------------------
// Spring follower (useSpring equivalent)
// ---------------------------------------------------------------------------

/** Something that calls back once per frame with the time since the last, in ms. */
export interface FrameTicker {
  add: (callback: (deltaMs: number) => void) => () => void;
}

/** requestAnimationFrame as a ticker — the library-free default. */
export const rafTicker: FrameTicker = {
  add(callback) {
    let last = performance.now();
    let frame = requestAnimationFrame(function tick(now) {
      callback(now - last);
      last = now;
      frame = requestAnimationFrame(tick);
    });
    return () => cancelAnimationFrame(frame);
  },
};

export interface SpringFollower {
  /** Chase a new target from wherever the value is now, keeping its velocity. */
  set: (target: number) => void;
  /** Move to a value instantly, with no motion. */
  jump: (value: number) => void;
  get: () => number;
  destroy: () => void;
}

/**
 * A value that follows its target through a spring, integrating the same
 * equation of motion Motion's `useSpring` solves — so a pointer-driven spring
 * reads the same in every build. Runs only while moving; `onUpdate` receives
 * each new value.
 */
export function createSpringFollower(
  initial: number,
  onUpdate: (value: number) => void,
  options: SpringOptions & { restSpeed?: number; ticker?: FrameTicker } = {},
): SpringFollower {
  const { stiffness = 100, damping = 10, mass = 1, ticker = rafTicker } = options;
  const restDelta = options.restDelta ?? 0.01;
  const restSpeed = options.restSpeed ?? 0.01;
  let value = initial;
  let target = initial;
  let velocity = 0;
  let stop: (() => void) | null = null;

  const step = (deltaMs: number) => {
    // Fixed 1ms sub-steps keep the integration stable for stiff springs and
    // independent of the frame rate.
    const steps = Math.min(Math.max(Math.round(deltaMs), 1), 250);
    for (let i = 0; i < steps; i++) {
      const force = -stiffness * (value - target) - damping * velocity;
      velocity += (force / mass) * 0.001;
      value += velocity * 0.001;
    }
    if (Math.abs(target - value) < restDelta && Math.abs(velocity) < restSpeed) {
      value = target;
      velocity = 0;
      stop?.();
      stop = null;
    }
    onUpdate(value);
  };

  return {
    set(next) {
      target = next;
      if (!stop && value !== target) stop = ticker.add(step);
    },
    jump(next) {
      stop?.();
      stop = null;
      value = target = next;
      velocity = 0;
      onUpdate(value);
    },
    get: () => value,
    destroy() {
      stop?.();
      stop = null;
    },
  };
}
